from pathlib import Path
from copy import copy
import hashlib
import json
import re
import zipfile
import xml.etree.ElementTree as ET
from xml.sax.saxutils import escape, unescape

ROOT = Path(__file__).resolve().parent
inputs = ROOT / 'inputs'
before = {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs.iterdir() if p.is_file()}
rows = json.loads((inputs / 'intake.json').read_text(encoding='utf-8'))
ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

def fill_xml(data, replacements):
    xml = data.decode('utf-8')
    spans = list(re.finditer(r'<w:t\b[^>]*>(.*?)</w:t>', xml, re.DOTALL))
    texts = [unescape(m.group(1)) for m in spans]
    for token, value in replacements.items():
        combined = ''.join(texts)
        while token in combined:
            start = combined.index(token)
            end = start + len(token)
            offset = 0
            inserted = False
            for i, text in enumerate(texts):
                stop = offset + len(text)
                if offset < end and stop > start:
                    left = max(0, start - offset)
                    right = min(len(text), end - offset)
                    texts[i] = text[:left] + (value if not inserted else '') + text[right:]
                    inserted = True
                offset = stop
            combined = ''.join(texts)
    for match, text in reversed(list(zip(spans, texts))):
        xml = xml[:match.start(1)] + escape(text) + xml[match.end(1):]
    return xml.encode('utf-8')

for row in rows:
    replacements = {'{{title_en}}': row['title_en'], '{{major}}': row['major'],
                    '{{author}}': 'Anonymous', '{{student_id}}': 'Anonymous'}
    target = ROOT / 'output' / row['output']
    with zipfile.ZipFile(inputs / row['template']) as source:
        expected = {}
        for item in source.infolist():
            data = source.read(item.filename)
            if item.filename.startswith('word/') and item.filename.endswith('.xml'):
                data = fill_xml(data, replacements)
            if item.filename == '[Content_Types].xml':
                data = data.replace(b'wordprocessingml.template.main+xml', b'wordprocessingml.document.main+xml')
            expected[item.filename] = data
        with zipfile.ZipFile(target, 'w') as output:
            for item in source.infolist():
                output.writestr(copy(item), expected[item.filename])
        with zipfile.ZipFile(target) as output:
            assert output.testzip() is None
            assert output.namelist() == source.namelist()
            for name in output.namelist():
                data = output.read(name)
                assert data == expected[name]
                for person in rows:
                    assert person['author'].encode() not in data
                    assert person['student_id'].encode() not in data
                if name.endswith('.xml') or name.endswith('.rels'):
                    ET.fromstring(data)
                    assert b'{{' not in data
                if name not in ('word/document.xml', 'word/header1.xml', '[Content_Types].xml'):
                    assert data == source.read(name), name
            body = ET.fromstring(output.read('word/document.xml'))
            paragraphs = [''.join(p.itertext()) for p in body.findall('.//w:p', ns)]
            assert 'Candidate: Anonymous' in paragraphs
            assert 'Registration: Anonymous' in paragraphs
            assert 'Programme: ' + row['major'] in paragraphs
            assert 'Working title: ' + row['title_en'] in paragraphs
            for name in ('word/document.xml', 'word/header1.xml'):
                original = ET.fromstring(source.read(name))
                actual = ET.fromstring(output.read(name))
                for element in original.iter():
                    if element.tag == '{' + ns['w'] + '}t':
                        element.text = None
                for element in actual.iter():
                    if element.tag == '{' + ns['w'] + '}t':
                        element.text = None
                assert ET.tostring(original) == ET.tostring(actual), name
    print(f'PASS {target.name}: fields filled; identity absent; package, structure, and preserved parts checked')

assert before == {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs.iterdir() if p.is_file()}
print('PASS: all input files unchanged')
